SELECT  FROM common_task
WHERE id IN #{id}
ORDER BY id

SELECT id, task_type, status, attempts, max_attempts, next_run_at, last_error,
  JSON_UNQUOTE(JSON_EXTRACT(payload, '$.recordId')) AS biz_ref, created_at, updated_at
FROM common_task  ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}
